using Sdcb.SimdCodecs.Jpeg;

namespace Sdcb.SimdCodecs.Tests;

/// <summary>
/// Minimal baseline (SOF0) JPEG writer for decoder tests, written from T.81 alone:
/// double-precision forward DCT (A.3.3), a zig-zag order generated by walking the
/// anti-diagonals, the Annex K Huffman tables, and the marker layout of Annex B.
/// It shares no code with the decoder (the tables come from the encoder's Annex K
/// transcription), and exists to produce streams no stock encoder will emit:
/// arbitrary sampling factors, non-interleaved component-per-scan baseline frames,
/// restart intervals on colour images, YCCK / plain four-component frames, and RGB.
/// </summary>
internal static class TestJpegWriter
{
    public sealed record Component(int Id, int H, int V);

    public sealed class Options
    {
        public int RestartInterval { get; init; }
        /// <summary>One interleaved scan (default), or one scan per component.</summary>
        public bool Interleaved { get; init; } = true;
        /// <summary>Emit an APP14 Adobe marker with this transform byte (0, 1, 2); null = none.</summary>
        public int? AdobeTransform { get; init; }
        public bool Jfif { get; init; } = true;
        public int Quality { get; init; } = 75;
    }

    /// <summary>
    /// Encodes <paramref name="sample"/>(component, x, y) — full-resolution samples —
    /// box-filtered down to each component's own resolution.
    /// </summary>
    public static byte[] Encode(int width, int height, Component[] comps, Func<int, int, int, byte> sample, Options? options = null)
    {
        var o = options ?? new Options();
        var hMax = comps.Max(c => c.H);
        var vMax = comps.Max(c => c.V);
        var mcuX = (width + 8 * hMax - 1) / (8 * hMax);
        var mcuY = (height + 8 * vMax - 1) / (8 * vMax);

        // Component planes at their own resolution, padded to the MCU grid by edge replication.
        var planes = new byte[comps.Length][];
        var cw = new int[comps.Length];
        var ch = new int[comps.Length];
        var pw = new int[comps.Length];
        var ph = new int[comps.Length];
        for (var k = 0; k < comps.Length; ++k)
        {
            var c = comps[k];
            var hs = hMax / c.H;
            var vs = vMax / c.V;
            cw[k] = (width * c.H + hMax - 1) / hMax;
            ch[k] = (height * c.V + vMax - 1) / vMax;
            pw[k] = mcuX * c.H * 8;
            ph[k] = mcuY * c.V * 8;
            var plane = new byte[pw[k] * ph[k]];
            for (var y = 0; y < ph[k]; ++y)
            {
                for (var x = 0; x < pw[k]; ++x)
                {
                    var sx = Math.Min(x, cw[k] - 1);
                    var sy = Math.Min(y, ch[k] - 1);
                    var sum = 0;
                    var n = 0;
                    for (var dy = 0; dy < vs; ++dy)
                    {
                        for (var dx = 0; dx < hs; ++dx)
                        {
                            sum += sample(k, Math.Min(sx * hs + dx, width - 1), Math.Min(sy * vs + dy, height - 1));
                            ++n;
                        }
                    }

                    plane[y * pw[k] + x] = (byte)((sum + n / 2) / n);
                }
            }

            planes[k] = plane;
        }

        var quant = new[] { QuantTable(o.Quality, 1.0), QuantTable(o.Quality, 1.6) };
        var dcTables = new[]
        {
            HuffTable(JpegEncoderTables.DcLumaBits, JpegEncoderTables.DcLumaValues),
            HuffTable(JpegEncoderTables.DcChromaBits, JpegEncoderTables.DcChromaValues),
        };
        var acTables = new[]
        {
            HuffTable(JpegEncoderTables.AcLumaBits, JpegEncoderTables.AcLumaValues),
            HuffTable(JpegEncoderTables.AcChromaBits, JpegEncoderTables.AcChromaValues),
        };
        int TableOf(int k) => k == 0 ? 0 : 1;

        var outp = new List<byte>();
        void Marker(byte m, ReadOnlySpan<byte> payload)
        {
            outp.Add(0xFF);
            outp.Add(m);
            var len = payload.Length + 2;
            outp.Add((byte)(len >> 8));
            outp.Add((byte)len);
            outp.AddRange(payload.ToArray());
        }

        outp.Add(0xFF);
        outp.Add(0xD8);
        if (o.Jfif)
            Marker(0xE0, [(byte)'J', (byte)'F', (byte)'I', (byte)'F', 0, 1, 1, 0, 0, 1, 0, 1, 0, 0]);
        if (o.AdobeTransform is { } t)
            Marker(0xEE, [(byte)'A', (byte)'d', (byte)'o', (byte)'b', (byte)'e', 0, 100, 0, 0, 0, 0, (byte)t]);

        var zz = ZigZag();
        for (var tq = 0; tq < 2; ++tq)
        {
            var dqt = new byte[65];
            dqt[0] = (byte)tq;
            for (var i = 0; i < 64; ++i)
                dqt[1 + i] = (byte)quant[tq][zz[i]];
            Marker(0xDB, dqt);
        }

        var sof = new List<byte> { 8, (byte)(height >> 8), (byte)height, (byte)(width >> 8), (byte)width, (byte)comps.Length };
        for (var k = 0; k < comps.Length; ++k)
            sof.AddRange([(byte)comps[k].Id, (byte)((comps[k].H << 4) | comps[k].V), (byte)TableOf(k)]);
        Marker(0xC0, sof.ToArray());

        for (var tc = 0; tc < 2; ++tc)
        {
            for (var th = 0; th < 2; ++th)
            {
                var table = tc == 0 ? dcTables[th] : acTables[th];
                var dht = new List<byte> { (byte)((tc << 4) | th) };
                dht.AddRange(table.Bits);
                dht.AddRange(table.Values);
                Marker(0xC4, dht.ToArray());
            }
        }

        if (o.RestartInterval > 0)
            Marker(0xDD, [(byte)(o.RestartInterval >> 8), (byte)o.RestartInterval]);

        var scans = o.Interleaved
            ? new[] { Enumerable.Range(0, comps.Length).ToArray() }
            : Enumerable.Range(0, comps.Length).Select(k => new[] { k }).ToArray();

        foreach (var scan in scans)
        {
            var sos = new List<byte> { (byte)scan.Length };
            foreach (var k in scan)
                sos.AddRange([(byte)comps[k].Id, (byte)((TableOf(k) << 4) | TableOf(k))]);
            sos.AddRange([0, 63, 0]);
            Marker(0xDA, sos.ToArray());

            var bw = new BitWriter(outp);
            var pred = new int[comps.Length];
            var units = 0;
            var rst = 0;

            void EncodeBlock(int k, int bx, int by)
            {
                var q = Quantize(planes[k], pw[k], bx * 8, by * 8, quant[TableOf(k)], zz);
                var diff = q[0] - pred[k];
                pred[k] = q[0];
                var dc = dcTables[TableOf(k)];
                var cat = Category(diff);
                bw.Put(dc.Code[cat], dc.Size[cat]);
                bw.Put(Magnitude(diff, cat), cat);

                var ac = acTables[TableOf(k)];
                var run = 0;
                for (var i = 1; i < 64; ++i)
                {
                    if (q[i] == 0)
                    {
                        ++run;
                        continue;
                    }

                    while (run > 15)
                    {
                        bw.Put(ac.Code[0xF0], ac.Size[0xF0]);
                        run -= 16;
                    }

                    var s = Category(q[i]);
                    var rs = (run << 4) | s;
                    bw.Put(ac.Code[rs], ac.Size[rs]);
                    bw.Put(Magnitude(q[i], s), s);
                    run = 0;
                }

                if (run > 0)
                    bw.Put(ac.Code[0], ac.Size[0]);
            }

            void Restart()
            {
                if (o.RestartInterval == 0 || units == 0 || units % o.RestartInterval != 0)
                    return;
                bw.FlushOnes();
                outp.Add(0xFF);
                outp.Add((byte)(0xD0 + (rst++ & 7)));
                Array.Clear(pred);
            }

            if (scan.Length > 1)
            {
                for (var my = 0; my < mcuY; ++my)
                {
                    for (var mx = 0; mx < mcuX; ++mx)
                    {
                        Restart();
                        foreach (var k in scan)
                            for (var y = 0; y < comps[k].V; ++y)
                                for (var x = 0; x < comps[k].H; ++x)
                                    EncodeBlock(k, mx * comps[k].H + x, my * comps[k].V + y);
                        ++units;
                    }
                }
            }
            else
            {
                // Non-interleaved: the component's own block grid, no MCU padding (A.2.2).
                var k = scan[0];
                var bxN = (cw[k] + 7) / 8;
                var byN = (ch[k] + 7) / 8;
                for (var by = 0; by < byN; ++by)
                {
                    for (var bx = 0; bx < bxN; ++bx)
                    {
                        Restart();
                        EncodeBlock(k, bx, by);
                        ++units;
                    }
                }
            }

            bw.FlushOnes();
        }

        outp.Add(0xFF);
        outp.Add(0xD9);
        return outp.ToArray();
    }

    /// <summary>
    /// Replaces the <paramref name="n"/>-th (1-based) RSTm marker with EOI and drops
    /// everything after it: a stream whose scan stops early at a restart boundary.
    /// </summary>
    public static byte[] CutAtRestart(byte[] jpeg, int n)
    {
        var seen = 0;
        for (var i = 0; i + 1 < jpeg.Length; ++i)
        {
            if (jpeg[i] == 0xFF && jpeg[i + 1] is >= 0xD0 and <= 0xD7 && ++seen == n)
            {
                var cut = jpeg[..(i + 2)];
                cut[i + 1] = 0xD9;
                return cut;
            }
        }

        throw new ArgumentException($"stream has fewer than {n} restart markers");
    }

    private static int[] ZigZag()
    {
        // zz[i] = natural (row-major) index of the i-th coefficient in zig-zag order.
        var zz = new int[64];
        var i = 0;
        for (var s = 0; s < 15; ++s)
        {
            for (var t = 0; t <= s; ++t)
            {
                var row = s % 2 == 0 ? s - t : t;
                var col = s - row;
                if (row < 8 && col < 8)
                    zz[i++] = row * 8 + col;
            }
        }

        return zz;
    }

    private static int[] QuantTable(int quality, double slope)
    {
        var scale = quality < 50 ? 50.0 / quality : (100 - quality) / 50.0;
        var q = new int[64];
        for (var v = 0; v < 8; ++v)
            for (var u = 0; u < 8; ++u)
                q[v * 8 + u] = Math.Clamp((int)Math.Round((4 + slope * 3 * (u + v)) * scale), 1, 255);
        return q;
    }

    private static int[] Quantize(byte[] plane, int stride, int x0, int y0, int[] quant, int[] zz)
    {
        Span<double> f = stackalloc double[64];
        for (var v = 0; v < 8; ++v)
        {
            for (var u = 0; u < 8; ++u)
            {
                var sum = 0.0;
                for (var y = 0; y < 8; ++y)
                    for (var x = 0; x < 8; ++x)
                        sum += (plane[(y0 + y) * stride + x0 + x] - 128)
                               * Math.Cos((2 * x + 1) * u * Math.PI / 16)
                               * Math.Cos((2 * y + 1) * v * Math.PI / 16);
                var cu = u == 0 ? 1 / Math.Sqrt(2) : 1;
                var cv = v == 0 ? 1 / Math.Sqrt(2) : 1;
                f[v * 8 + u] = 0.25 * cu * cv * sum;
            }
        }

        var q = new int[64];
        for (var i = 0; i < 64; ++i)
            q[i] = Math.Clamp((int)Math.Round(f[zz[i]] / quant[zz[i]]), i == 0 ? -2047 : -1023, i == 0 ? 2047 : 1023);
        return q;
    }

    private static int Category(int v)
    {
        var a = Math.Abs(v);
        var n = 0;
        while (a > 0)
        {
            ++n;
            a >>= 1;
        }

        return n;
    }

    private static int Magnitude(int v, int cat) => v >= 0 ? v : v + (1 << cat) - 1;

    private sealed record Huff(int[] Code, int[] Size, byte[] Bits, byte[] Values);

    /// <summary>Derives every symbol's code from a T.81 Annex K BITS / HUFFVAL pair (Annex C).</summary>
    private static Huff HuffTable(ReadOnlySpan<byte> bits, ReadOnlySpan<byte> values)
    {
        var code = new int[256];
        var size = new int[256];
        int next = 0, k = 0;
        for (var len = 1; len <= 16; ++len, next <<= 1)
        {
            for (var i = 0; i < bits[len - 1]; ++i, ++k, ++next)
            {
                code[values[k]] = next;
                size[values[k]] = len;
            }
        }

        return new Huff(code, size, bits.ToArray(), values.ToArray());
    }

    private sealed class BitWriter(List<byte> output)
    {
        private int _acc;
        private int _n;

        public void Put(int value, int count)
        {
            for (var i = count - 1; i >= 0; --i)
            {
                _acc = (_acc << 1) | ((value >> i) & 1);
                if (++_n == 8)
                    Emit();
            }
        }

        public void FlushOnes()
        {
            while (_n != 0)
                Put(1, 1);
        }

        private void Emit()
        {
            var b = (byte)_acc;
            output.Add(b);
            if (b == 0xFF)
                output.Add(0x00);
            _acc = 0;
            _n = 0;
        }
    }
}
